package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Fraction_divideBy_TriageGen2Test {

    @Test
    public void testDivideBy_ValidFraction() {
        // Test case: 1/2 divided by 3/4 should be (1/2) * (4/3) = 4/6 = 2/3
        Fraction f1 = Fraction.getFraction(1, 2);
        Fraction f2 = Fraction.getFraction(3, 4);
        Fraction expected = Fraction.getReducedFraction(2, 3);
        Fraction result = f1.divideBy(f2);

        assertEquals("The result of 1/2 divided by 3/4 should be 2/3", expected, result);
    }

    @Test
    public void testDivideBy_NegativeFraction() {
        // Test case: 1/2 divided by -1/2 should be -1
        Fraction f1 = Fraction.getFraction(1, 2);
        Fraction f2 = Fraction.getFraction(-1, 2);
        Fraction expected = Fraction.getFraction(-1, 1);
        Fraction result = f1.divideBy(f2);

        assertEquals("The result of 1/2 divided by -1/2 should be -1/1", expected, result);
    }

    @Test
    public void testDivideBy_NullParameter() {
        // Test case: Passing null should throw IllegalArgumentException
        Fraction f1 = Fraction.getFraction(1, 1);
        try {
            f1.divideBy(null);
            fail("Expected IllegalArgumentException was not thrown");
        } catch (IllegalArgumentException e) {
            assertEquals("The fraction must not be null", e.getMessage());
        }
    }

    @Test
    public void testDivideBy_ZeroDenominatorFraction() {
        // Test case: Dividing by a fraction where numerator is 0 should throw ArithmeticException
        Fraction f1 = Fraction.getFraction(1, 1);
        Fraction f2 = Fraction.getFraction(0, 5);
        try {
            f1.divideBy(f2);
            fail("Expected ArithmeticException was not thrown");
        } catch (ArithmeticException e) {
            assertEquals("The fraction to divide by must not be zero", e.getMessage());
        }
    }

    @Test
    public void testDivideBy_WholeNumber() {
        // Test case: 1/1 divided by 2/1 should be 1/2
        Fraction f1 = Fraction.getFraction(1, 1);
        Fraction f2 = Fraction.getFraction(2, 1);
        Fraction expected = Fraction.getFraction(1, 2);
        Fraction result = f1.divideBy(f2);

        assertEquals("The result of 1 divided by 2 should be 1/2", expected, result);
    }
}
